export type ColType = 'number' | 'date' | 'text';

export interface ColStats {
  name: string;
  type: ColType;
  count: number;
  nullCount: number;
  uniqueCount: number;
  min?: number;
  max?: number;
}

export interface ParsedCsv {
  headers: string[];
  rows: string[][];
  stats: ColStats[];
}

export function detectSeparator(text: string): string {
  const firstLine = text.split('\n')[0] ?? '';
  const counts = { ',': 0, '\t': 0, ';': 0 };
  for (const ch of firstLine) {
    if (ch in counts) counts[ch as keyof typeof counts]++;
  }
  const best = Object.entries(counts).sort((a, b) => b[1] - a[1])[0];
  return best[1] > 0 ? best[0] : ',';
}

export function parseCSV(text: string, sep?: string): ParsedCsv {
  const separator = sep ?? detectSeparator(text);
  const lines = text.trim().split(/\r?\n/).filter(l => l.trim() !== '');
  if (lines.length === 0) return { headers: [], rows: [], stats: [] };

  const parseLine = (line: string): string[] => {
    const result: string[] = [];
    let field = '';
    let inQuotes = false;
    for (let i = 0; i < line.length; i++) {
      const ch = line[i];
      if (ch === '"') {
        if (inQuotes && line[i + 1] === '"') { field += '"'; i++; }
        else inQuotes = !inQuotes;
      } else if (ch === separator && !inQuotes) {
        result.push(field.trim());
        field = '';
      } else {
        field += ch;
      }
    }
    result.push(field.trim());
    return result;
  };

  const headers = parseLine(lines[0]);
  const rows = lines.slice(1).map(parseLine);

  const stats: ColStats[] = headers.map((name, ci) => {
    const values = rows.map(r => r[ci] ?? '');
    const nonNull = values.filter(v => v !== '' && v !== null);
    const type = detectColumnType(nonNull);
    const unique = new Set(values).size;
    let min: number | undefined, max: number | undefined;
    if (type === 'number') {
      const nums = nonNull.map(Number).filter(n => !isNaN(n));
      if (nums.length) { min = Math.min(...nums); max = Math.max(...nums); }
    }
    return { name, type, count: values.length, nullCount: values.length - nonNull.length, uniqueCount: unique, min, max };
  });

  return { headers, rows, stats };
}

export function detectColumnType(values: string[]): ColType {
  if (values.length === 0) return 'text';
  const sample = values.slice(0, 20);
  const numericCount = sample.filter(v => v !== '' && !isNaN(Number(v))).length;
  if (numericCount / sample.length > 0.8) return 'number';
  const dateCount = sample.filter(v => !isNaN(Date.parse(v)) && v.length > 4).length;
  if (dateCount / sample.length > 0.7) return 'date';
  return 'text';
}
